const net = require(\"net\");
const s = net.connect(9229, \"127.0.0.1\", () => {
  const req = \"GET /c5a975fa-829b-4e8d-84e2-8815752c1ae9 HTTP/1.1\\r\\n\" +
    \"Host: 127.0.0.1:9229\\r\\n\" +
    \"Upgrade: websocket\\r\\n\" +
    \"Connection: Upgrade\\r\\n\" +
    \"Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\\r\\n\" +
    \"Sec-WebSocket-Version: 13\\r\\n\\r\\n\";
  s.write(req);
});

let upgraded = false;
let buffer = Buffer.alloc(0);

s.on(\"data\", (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  if ("'!upgraded) {
    const idx = buffer.indexOf("'"\\r\\n\\r\\n\");
    if (idx "'!== -1) {
      upgraded = true;
      buffer = buffer.slice(idx + 4);
      sendJson({
        id: 1,
        method: "Runtime.evaluate",
        params: {
          expression: "JSON.stringify({ memory: process.memoryUsage() })",
          returnByValue: true
        }
      });
    }
  } else {
    // Read ws frame
    if (buffer.length >= 2) {
      const len = buffer[1] & 0x7f;
      let offset = 2;
      let payloadLen = len;
      if (len === 126) {
        payloadLen = buffer.readUInt16BE(2);
        offset = 4;
      } else if (len === 127) {
        payloadLen = Number(buffer.readBigUInt64BE(2));
        offset = 10;
      }
      if (buffer.length >= offset + payloadLen) {
        const payload = buffer.slice(offset, offset + payloadLen).toString();
        console.log("PAYLOAD:", payload);
        s.end();
      }
    }
  }
});

function sendJson(obj) {
  const payload = Buffer.from(JSON.stringify(obj));
  const len = payload.length;
  let header;
  const mask = Buffer.from([0x12, 0x34, 0x56, 0x78]);
  if (len < 126) {
    header = Buffer.from([0x81, 0x80 | len]);
  } else if (len < 65536) {
    header = Buffer.alloc(4);
    header[0] = 0x81;
    header[1] = 0x80 | 126;
    header.writeUInt16BE(len, 2);
  }
  const masked = Buffer.alloc(len);
  for (let i = 0; i < len; i++) {
    masked[i] = payload[i] ''^ mask[i % 4];
  }
  s.write(Buffer.concat([header, mask, masked]));
}
