let upgraded = false;
let buffer = Buffer.alloc(0);

s.on(\"data\", (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  if ("'!upgraded) {
    const idx = buffer.indexOf("'"\\r\\n\\r\\n\");
    if (idx "'!== -1) {
      upgraded = true;
      buffer = buffer.slice(idx + 4);
      sendJson({
        id: 1,
        method: "Runtime.evaluate",
        params: {
          expression: "Object.values(process.mainModule.constructor._cache).find(m => m.filename.includes('"\\\"statements\\\")).exports.statementFor\",
          returnByValue: false
        }
      });
    }
  } else {
    while (buffer.length >= 2) {
      const len = buffer[1] & 0x7f;
      let offset = 2;
      let payloadLen = len;
      if (len === 126) {
        if (buffer.length < 4) break;
        payloadLen = buffer.readUInt16BE(2);
        offset = 4;
      } else if (len === 127) {
        if (buffer.length < 10) break;
        payloadLen = Number(buffer.readBigUInt64BE(2));
        offset = 10;
      }
      if (buffer.length < offset + payloadLen) break;
      const payload = buffer.slice(offset, offset + payloadLen).toString();
      buffer = buffer.slice(offset + payloadLen);
      const json = JSON.parse(payload);
      if (json.id === 1) {
        const objId = json.result.result.objectId;
        sendJson({
          id: 2,
          method: \"Runtime.getProperties\",
          params: { objectId: objId }
        });
      } else if (json.id === 2) {
        const internal = json.result.internalProperties || [];
        const scopesProp = internal.find(p => p.name === \"[[Scopes]]\");
        if (scopesProp) {
          sendJson({
            id: 3,
            method: \"Runtime.getProperties\",
            params: { objectId: scopesProp.value.objectId }
          });
        } else {
          console.log(\"No scopes\");
          s.end();
        }
      } else if (json.id === 3) {
        const scopes = json.result.result;
        const closure = scopes.find(s => s.value && s.value.description && s.value.description.includes(\"closure\"));
        if (closure) {
          sendJson({
            id: 4,
            method: \"Runtime.getProperties\",
            params: { objectId: closure.value.objectId }
          });
        } else {
          console.log(\"Scopes:\", JSON.stringify(scopes));
          s.end();
        }
      } else if (json.id === 4) {
        const props = json.result.result;
        const cacheProp = props.find(p => p.name === \"cache\");
        if (cacheProp) {
          sendJson({
            id: 5,
            method: \"Runtime.getProperties\",
            params: { objectId: cacheProp.value.objectId }
          });
        } else {
          console.log(\"Props:\", props.map(p => p.name));
          s.end();
        }
      } else if (json.id === 5) {
        const keys = json.result.result.map(p => p.name);
        console.log(\"CACHE COUNT:\", keys.length);
        console.log(\"SAMPLE KEYS:\", keys.slice(0, 10));
        s.end();
      }
    }
  }
});

