const { Worker, Queue } = require(\"bullmq\");
const IORedis = require(\"ioredis\");
const connection = new IORedis(\"redis://redis:6379\", { maxRetriesPerRequest: null });
const partner = require(\"./src/partner\");

const q = new Queue(\"test-batch-notif\", { connection });

let completed = 0;
let failed = 0;

const worker = new Worker(\"test-batch-notif\", async (job) => {
  await partner.request(\"/v1/notifications\", {
    method: \"POST\",
    body: { notificationId: job.data.id, userId: 1, message: \"batch test\" },
    headers: { authorization: \"Bearer pk_live_7f3a9c\" },
  });
}, {
  connection,
  concurrency: 5,
  limiter: {
    max: 5,
    duration: 1000,
  },
  settings: {
    backoffStrategy: (attemptsMade, type, err) => {
      const waitSec = (err && err.retryAfterSec) || 1;
      return waitSec * 1000 + 100;
    }
  }
});

worker.on(\"completed\", () => completed++);
worker.on(\"failed\", (job, err) => {
  failed++;
  console.log(\"Job failed:\", job.id, err.message);
});

async function run() {
  const t0 = Date.now();
  console.log(\"Enqueuing 20 jobs...\");
  for (let i = 0; i < 20; i++) {
    await q.add(\"notification\", { id: "'`batch-test-${Date.now()}-${i}` }, {
      attempts: 5,
      backoff: { type: "custom" }
    });
  }

  const check = setInterval(async () => {
    console.log(`Progress: completed=${completed}, failed=${failed}, elapsed=${Date.now() - t0}ms`);
    if (completed + failed >= 20) {
      clearInterval(check);
      await worker.close();
      await q.obliterate({ force: true });
      await q.close();
      await connection.quit();
      console.log(`Finished: ${completed}/20 succeeded!`);
      process.exit(0);
    }
  }, 500);
}

run();
EOF
